package com.cookly.seguridad;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.authority.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class FiltroJwt extends OncePerRequestFilter { private final ServicioToken servicio; public FiltroJwt(ServicioToken s){servicio=s;} @Override protected void doFilterInternal(HttpServletRequest solicitud,HttpServletResponse respuesta,FilterChain cadena)throws ServletException,java.io.IOException { String cabecera=solicitud.getHeader("Authorization"); if(cabecera!=null&&cabecera.startsWith("Bearer ")) try { var datos=servicio.validar(cabecera.substring(7)); var autoridad=new SimpleGrantedAuthority("ROLE_"+datos.get("rol",String.class)); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(datos.getSubject(),null,java.util.List.of(autoridad))); }catch(Exception ignorada){} cadena.doFilter(solicitud,respuesta); } }
